const item = $input.first().json;

if (item.success && item.exportId) {
  return [{
    json: {
      success: true,
      status: 'completed',
      statusCode: 200,
      exportId: item.exportId,
      fileName: item.fileName,
      format: item.format,
      contentType: item.contentType,
      size: item.size,
      downloadUrl: item.downloadUrl,
      message: 'Tài liệu đã được tạo thành công bởi Backend qua Flow 12.'
    }
  }];
}

const statusCode = item.statusCode || (item.response && item.response.status) || 500;
const errorMsg = item.message || item.error || 'Quá trình sinh tài liệu thất bại.';

return [{
  json: {
    success: false,
    status: 'failed',
    statusCode: statusCode,
    error: item.error || 'EXPORT_GENERATION_FAILED',
    message: errorMsg
  }
}];
